//! Rust port of `tests/test4.cpp`.
//!
//! Builds a polygon out of `n` overlapping axis-aligned squares, hands it to
//! the earcut triangulator and prints the resulting vertex indices separated
//! by spaces.
//!
//! Build standalone with `rustc -O test4.rs` (the modules below are pulled in
//! by path), or via `cargo build --release`, which builds the same file as the
//! `test4` binary target alongside the `earcut_test4` library.

#[path = "src/cli.rs"]
mod cli;

// The library exposes more than this one entry point needs; when test4.rs is
// compiled standalone with rustc the rest is legitimately unreachable.
#[allow(dead_code)]
#[path = "src/earcut/mod.rs"]
mod earcut;

#[path = "src/polygon.rs"]
mod polygon;

use std::io::Write;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut n: i32 = 4;
    if args.len() > 1 {
        n = cli::atoi(&args[1]);
    }

    let polygon = polygon::overlapping_squares(n);

    let indices = earcut::earcut(&polygon);

    // `std::cout << idx << " "` for each index: no separator logic, no
    // trailing newline.
    let mut out = String::new();
    for idx in &indices {
        out.push_str(&idx.to_string());
        out.push(' ');
    }

    let stdout = std::io::stdout();
    let mut handle = stdout.lock();
    let _ = handle.write_all(out.as_bytes());
    let _ = handle.flush();
}

#include <iostream>
#include <vector>
#include <array>
#include "../earcut.hpp"

int main(int argc, char* argv[]) {
    int n = 4;
    if (argc > 1) {
        n = std::atoi(argv[1]);
    }

    std::vector<std::vector<std::array<double, 2>>> polygon;

    for (int i = 0; i < n; i++) {
        std::vector<std::array<double, 2>> ring;
        double offset = i * 2;
        ring.push_back({offset, offset});
        ring.push_back({offset + n, offset});
        ring.push_back({offset + n, offset + n});
        ring.push_back({offset, offset + n});
        polygon.push_back(ring);
    }

    auto indices = mapbox::earcut<uint32_t>(polygon);

    for (auto idx : indices) {
        std::cout << idx << " ";
    }
    return 0;
}


