//! Command line helpers.
//!
//! `test4.cpp` reads its single optional argument with `std::atoi`, which has
//! semantics no `std` Rust parser reproduces: leading whitespace is skipped, an
//! optional sign is accepted, parsing stops at the first non-digit, a string
//! with no digits at all yields `0`, and out-of-range values are truncated to
//! `int` rather than reported as an error.

/// Reimplementation of C's `atoi` as glibc provides it: `(int) strtol(s, NULL, 10)`.
///
/// `strtol` saturates at `LONG_MIN` / `LONG_MAX` (64-bit on this platform) and
/// the result is then truncated to 32 bits, so e.g. `"99999999999999999999"`
/// becomes `-1` just as it does in C.
pub fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0usize;

    // isspace(): space, \t, \n, \v, \f, \r
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }

    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }

    // Accumulate in i64 (== C `long` here) with saturation, mirroring strtol.
    let mut acc: i64 = 0;
    let mut saturated = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let digit = i64::from(bytes[i] - b'0');
        if !saturated {
            match acc.checked_mul(10).and_then(|v| v.checked_add(digit)) {
                Some(v) => acc = v,
                None => saturated = true,
            }
        }
        i += 1;
    }

    let value = if saturated {
        if negative {
            i64::MIN
        } else {
            i64::MAX
        }
    } else if negative {
        -acc
    } else {
        acc
    };

    value as i32
}

#[cfg(test)]
mod tests {
    use super::atoi;

    #[test]
    fn matches_c_atoi() {
        assert_eq!(atoi(""), 0);
        assert_eq!(atoi("abc"), 0);
        assert_eq!(atoi("7abc"), 7);
        assert_eq!(atoi(" 9"), 9);
        assert_eq!(atoi("+6"), 6);
        assert_eq!(atoi("-3"), -3);
        assert_eq!(atoi("0"), 0);
        assert_eq!(atoi("  \t-12x34"), -12);
        assert_eq!(atoi("2147483648"), -2147483648);
        assert_eq!(atoi("99999999999999999999"), -1);
    }
}
